// Search over window.LVS_API (names and signatures from the spec, text from docs/reference.md;
// generated by tools/build_site_data.py).
// Pure: no DOM, so it can be tested in node.

(function (root) {
  'use strict';

  // The detail blocks of an entry ({p}, {ul}, {code}) as one string, cached on the entry.
  function docText(e) {
    if (e._text === undefined) {
      e._text = (e.doc || []).map(b => b.p || (b.ul ? b.ul.join(' ') : '') || b.code || '').join(' ');
    }
    return e._text;
  }

  // Every whitespace-separated term must be a substring of name, kind, summary or detail text.
  // Best first: exact name, name prefix, name substring, then summary matches, then
  // matches in the detail text only; ties keep the entries' own order.
  function searchApi(entries, query, kind) {
    const terms = String(query || '').toLowerCase().split(/\s+/).filter(Boolean);
    const scored = [];
    entries.forEach((e, i) => {
      if (kind && kind !== 'all' && e.kind !== kind) return;
      const name = e.name.toLowerCase();
      const hay = name + ' ' + e.kind + ' ' + (e.summary || '').toLowerCase();
      let rank = 3;
      if (!terms.every(t => hay.includes(t))) {
        const full = hay + ' ' + docText(e).toLowerCase();
        if (!terms.every(t => full.includes(t))) return;
        rank = 4;
      }
      if (terms.length && rank === 3) {
        const first = terms[0];
        if (name === first) rank = 0;
        else if (name.startsWith(first)) rank = 1;
        else if (name.includes(first)) rank = 2;
      }
      scored.push({ e, rank, i });
    });
    scored.sort((a, b) => a.rank - b.rank || a.i - b.i);
    return scored.map(s => s.e);
  }

  root.LVS_searchApi = searchApi;
  if (typeof module !== 'undefined' && module.exports) module.exports = searchApi;
})(typeof window !== 'undefined' ? window : globalThis);
